/* No framework or external chart dependency. All displayed operational metrics derive from the dataset. */
let D, series, role='manager', page='overview', selected=null, scenarioRows=[];
const $=s=>document.querySelector(s), $$=s=>[...document.querySelectorAll(s)];
const fmt=(n,d=0)=>Number(n).toLocaleString('en-US',{maximumFractionDigits:d,minimumFractionDigits:d});
const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
let states={};try{states=JSON.parse(localStorage.getItem('meterwise-review-v2')||'{}')}catch(e){}
const state=a=>states[a.id]||'new';
const building=id=>D.buildings.find(b=>b.id===id);
const stamp=i=>new Date(new Date(D.start).getTime()+i*900000).toLocaleString('en-US',{timeZone:'America/Los_Angeles',month:'short',day:'numeric',hour:'2-digit',minute:'2-digit',hour12:false});
const dayIndex=date=>Math.round((Date.parse(date+'T00:00:00-07:00')-Date.parse(D.start))/86400000);
const ids=()=>$('#building').value==='ALL'?D.buildings.map(b=>b.id):[$('#building').value];
const bounds=()=>{let end=(dayIndex($('#date').value)+1)*96;return {start:Math.max(42*96,end-Number($('#window').value)*96),end}};
const overlaps=(a,e)=>a.building===e.building && a.start<e.end && a.end>e.start;
const visibleAlerts=()=>{const {start,end}=bounds();return D.alerts.filter(a=>ids().includes(a.building)&&a.start<end&&a.end>start).sort((a,b)=>({High:0,Medium:1}[a.priority]-{High:0,Medium:1}[b.priority])||b.start-a.start)};
const rowOf=(bid,i)=>series[bid][i];
const labels={missing:'Telemetry gap',stale:'Flatlined readings',reactive:'Reactive demand',demand:'Demand deviation',context:'Contextual anomaly'};
const advice={missing:'Check the gateway and missing-interval backfill. A communications gap does not establish a power outage.',stale:'Verify timestamps and the gateway cache, then request a fresh meter reading.',reactive:'Compare reactive demand with equipment status. Confirm the cause with suitable power-quality measurements.',demand:'Compare the BMS schedule, occupancy, weather, and equipment logs. The meter alone cannot establish the cause.'};
function notify(text){$('#toast').textContent=text;$('#toast').classList.add('show');setTimeout(()=>$('#toast').classList.remove('show'),2800)}
function navigate(p){page=p;location.hash=p;window.scrollTo({top:0,behavior:'instant'});$$('.page').forEach(el=>el.classList.toggle('active',el.id===p));$$('nav button').forEach(el=>el.classList.toggle('active',el.dataset.page===p));const title={overview:['YOUR CAMPUS, AT A GLANCE','A clearer picture of your energy.','Spot unusual behavior. Understand the signal. Take the next step.'],alerts:['FROM SIGNAL TO ACTION','Every alert deserves context.','Review the evidence, choose a next step, and keep the team informed.'],lab:['CONTROLLED EXPERIMENTS','Make the unusual, on purpose.','Explore how different patterns affect a simple anomaly detector.'],data:['TRANSPARENT BY DESIGN','Know what’s behind the signal.','A reproducible dataset, clear assumptions, and an honest baseline.']}[p];$('#crumb').textContent={overview:'Campus overview',alerts:'Alert inbox',lab:'Scenario lab',data:'Data & methodology'}[p];['eyebrow','page-title','page-description'].forEach((id,i)=>$('#'+id).textContent=title[i]);$('.toolbar').classList.toggle('hidden',p==='data'||p==='lab');$('#export').classList.toggle('hidden',p==='data');render();}
function aggregate(bids,start,end){let rows=[];for(let i=start;i<end;i++){let rs=bids.map(id=>rowOf(id,i));const good=rs.filter(r=>r.p!==null);rows.push({i,t:rs[0].t,p:good.length===rs.length?good.reduce((s,r)=>s+r.p,0):null,expected:rs.reduce((s,r)=>s+r.expected,0),band:rs.reduce((s,r)=>s+r.scale*building(r.building).threshold,0),flag:rs.some(r=>r.flag),temp:rs[0].temp})}return rows;}
function kpi(label,value,unit,foot,emphasis=false,icon='↗'){return `<div class="kpi ${emphasis?'emphasis':''}"><div class="label">${label}<span>${icon}</span></div><div class="value">${value}<small>${unit}</small></div><div class="foot">${foot}</div></div>`}
function drawChart(target,rows,{alerts=[],height=255,compact=false,threshold=0,title='Demand',supportWindows=[]}={}){
 const el=$(target);if(!rows.length){el.innerHTML='<div class="empty">No readings for this window.</div>';return;}
 const W=800,H=height,L=48,R=14,T=20,B=32,w=W-L-R,h=H-T-B;
 const vals=rows.flatMap(r=>[r.p,r.expected+(r.band||threshold*r.scale||0),r.expected-(r.band||threshold*r.scale||0)]).filter(v=>v!==null&&Number.isFinite(v));
 let lo=Math.min(0,...vals),hi=Math.max(...vals);let pad=(hi-lo)*.12||10;hi+=pad;lo-=pad*.35;
 const x=j=>L+j/Math.max(1,rows.length-1)*w, y=v=>T+(hi-v)/(hi-lo)*h;
 const num=v=>fmt(v,0);let html=`<svg viewBox="0 0 ${W} ${H}" role="img" aria-label="${esc(title)}. Observed and expected demand in kilowatts."><defs><linearGradient id="fill-${target.slice(1)}" x1="0" y1="0" x2="0" y2="1"><stop stop-color="#47876b" stop-opacity=".10"/><stop offset="1" stop-color="#47876b" stop-opacity="0"/></linearGradient></defs>`;
 for(let k=0;k<=4;k++){let val=lo+(hi-lo)*k/4,yy=y(val);html+=`<line x1="${L}" x2="${W-R}" y1="${yy}" y2="${yy}" stroke="#edf0e7" stroke-dasharray="3 4"/><text x="${L-10}" y="${yy+3}" text-anchor="end" class="svg-label">${num(val)}</text>`}
 html+=`<text x="${L}" y="10" class="svg-label">kW · net import</text>`;
 const band=r=>r.band||threshold*r.scale||0;
 const upper=rows.map((r,j)=>`${x(j)},${y(r.expected+band(r))}`).join(' '),lower=rows.map((r,j)=>`${x(j)},${y(r.expected-band(r))}`).reverse().join(' ');
 html+=`<polygon points="${upper} ${lower}" fill="#edf2e7"/>`;
 for(const a of [...alerts].sort((a,b)=>(a.priority==='High')-(b.priority==='High'))){if(a.end<=rows[0].i||a.start>rows.at(-1).i)continue;const xx=x(Math.max(0,a.start-rows[0].i)),xe=x(Math.min(rows.length-1,a.end-rows[0].i)),color=a.priority==='High'?'#c93636':'#e7b400';html+=`<rect x="${xx}" y="${T}" width="${Math.max(4,xe-xx)}" height="${h}" fill="${color}" opacity=".14"/><rect x="${xx}" y="${T}" width="${Math.max(4,xe-xx)}" height="4" fill="${color}"/>`}
 const path=(key)=>{let connected=false;return rows.map((r,j)=>{const v=r[key];if(v===null||!Number.isFinite(v)){connected=false;return ''}let cmd=connected?'L':'M';connected=true;return `${cmd}${x(j).toFixed(2)},${y(v).toFixed(2)}`}).join(' ')};
 html+=`<path d="${path('expected')}" fill="none" stroke="#a2af98" stroke-width="1.6" stroke-dasharray="5 4"/><path d="${path('p')}" fill="none" stroke="#347a60" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"/>`;
 for(const a of [...alerts].sort((a,b)=>(a.priority==='High')-(b.priority==='High'))){const sub=rows.map((r,j)=>({r,j})).filter(({r})=>r.i>=a.start&&r.i<a.end);if(!sub.length)continue;const color=a.priority==='High'?'#c93636':'#b48600';let connect=false;const line=sub.map(({r,j})=>{if(r.p===null){connect=false;return ''}const cmd=connect?'L':'M';connect=true;return `${cmd}${x(j)},${y(r.p)}`}).join(' ');html+=`<path d="${line}" fill="none" stroke="${color}" stroke-width="3.3"/>`;for(const {r,j} of [sub[0],...(sub.length>1?[sub.at(-1)]:[])]){if(r.p!==null)html+=`<circle cx="${x(j)}" cy="${y(r.p)}" r="3.5" fill="${color}" stroke="white" stroke-width="1"/>`;}}
 for(let k=0;k<=4;k++){const j=Math.round(k*(rows.length-1)/4);const t=new Date(rows[j].t);const txt=rows.length<=96?t.toLocaleTimeString('en-US',{timeZone:'America/Los_Angeles',hour:'2-digit',minute:'2-digit',hour12:false}):t.toLocaleDateString('en-US',{timeZone:'America/Los_Angeles',month:'short',day:'numeric'});html+=`<text x="${x(j)}" y="${H-10}" text-anchor="${k===0?'start':k===4?'end':'middle'}" class="svg-label">${txt}</text>`}
 html+=`<line class="hover-line" x1="0" x2="0" y1="${T}" y2="${T+h}" stroke="#6d8d6c" stroke-dasharray="3 3" opacity="0"/><rect class="hover-zone" x="${L}" y="${T}" width="${w}" height="${h}" fill="transparent"/></svg><div class="chart-tip"></div>`;el.innerHTML=html;
 const svg=el.querySelector('svg'),zone=el.querySelector('.hover-zone'),line=el.querySelector('.hover-line'),tip=el.querySelector('.chart-tip');
 zone.addEventListener('pointermove',ev=>{const rect=svg.getBoundingClientRect(),xx=(ev.clientX-rect.left)/rect.width*W,j=Math.max(0,Math.min(rows.length-1,Math.round((xx-L)/w*(rows.length-1)))),r=rows[j];line.setAttribute('x1',x(j));line.setAttribute('x2',x(j));line.setAttribute('opacity',1);tip.innerHTML=`${stamp(r.i)} PDT<br>Observed: ${r.p===null?'Missing':fmt(r.p,1)+' kW'}<br>Expected: ${fmt(r.expected,1)} kW${alerts.filter(a=>a.start<=r.i&&a.end>r.i).map(a=>'<br>'+esc(a.priority||'Medium')+' · '+esc(a.likely_type||a.title||'Flagged interval')).join('')}`;tip.style.display='block';tip.style.left=Math.min(el.clientWidth-210,Math.max(5,ev.clientX-rect.left+10))+'px';tip.style.top='25px'});
 zone.addEventListener('pointerleave',()=>{line.setAttribute('opacity',0);tip.style.display='none'});
 WorkspaceUI.decorateChart(el,rows,alerts,{L,T,w,h,W,supportWindows});
}
function render(){if(!D)return;const va=visibleAlerts();$('#nav-count').textContent=va.filter(a=>state(a)==='new').length;if(page==='overview')renderOverview();if(page==='alerts')renderInbox();if(page==='lab'){runScenario();renderBenchmark();InsightUI.sensitivity()}}
function renderOverviewBase(){const {start,end}=bounds(),bids=ids(),rows=aggregate(bids,start,end),all=bids.flatMap(id=>series[id].slice(start,end)),va=visibleAlerts();
 const measured=all.filter(r=>r.p!==null),energy=measured.reduce((s,r)=>s+Math.max(0,r.p)*.25,0),excess=all.filter(r=>(r.flag==='demand'||r.context_flag)&&r.p!==null).reduce((s,r)=>s+Math.max(0,r.p-r.expected)*.25,0),coverage=measured.length/all.length*100;
 $('#kpis').innerHTML=kpi('Imported energy',fmt(energy/1000,1),'MWh',`${fmt(measured.length)} reported meter intervals`)+kpi('Alerts to review',va.filter(a=>state(a)==='new').length,'',`<b>${va.filter(a=>a.priority==='High').length} high-priority</b> · ${va.length} total episodes`,true,'◎')+kpi('Flagged excess demand',fmt(excess),'kWh','Positive residual during demand / history alerts · estimate','', '⌁')+kpi('Data completeness',fmt(coverage,1),'%',`${all.length-measured.length} missing intervals · stale values included`,false,'◷');
 if(role==='engineer'){const reactive=measured.reduce((s,r)=>s+r.q,0)/Math.max(1,measured.length),peak=Math.max(...measured.map(r=>r.p)),current=Math.max(...measured.map(r=>r.amps)),quality=all.filter(r=>['missing','stale'].includes(r.flag)).length;$('#kpis').innerHTML=kpi('Peak interval net demand',fmt(peak),'kW','Maximum reported 15-minute average')+kpi('Mean reactive power',fmt(reactive,1),'kvar','Reported values · positive inductive',true,'⌁')+kpi('Peak equivalent current',fmt(current),'A','Balanced three-phase estimate · modeled')+kpi('Quality-flagged intervals',fmt(quality),'', 'Missing or flatline rule · review timestamps');}
 $('#chart-subtitle').textContent=`${bids.length===6?'All 6 buildings':building(bids[0]).name} · ${stamp(start).split(',')[0]} – ${stamp(end-1).split(',')[0]}`;
 $('#chart-caption').textContent='PDT · Red = high · Yellow = medium · gaps stay missing';drawChart('#chart',rows,{alerts:va,title:'Campus demand'});
 const focus=va.find(a=>state(a)==='new')||va[0];
 $('#spotlight').innerHTML=focus?`<span class="alert-type">${esc(labels[focus.kind])}</span><h3>${esc(building(focus.building).name)}</h3><p>${esc(focus.title)}. ${fmt((focus.end-focus.start)*.25,2)} hours flagged in this episode.</p><button class="button" data-alert="${focus.id}">Review the evidence ↗</button><div class="tiny">${stamp(focus.start)} PDT · ${state(focus)}</div>`:'<h3>No alerts in this window.</h3><p>Choose a longer window or try an injected scenario.</p><button class="button" data-page="lab">Open scenario lab ↗</button>';
 $('#chart-detail').onclick=()=>{if(focus)openAlert(focus.id);else navigate('alerts')};
 $('#building-cards').innerHTML=D.buildings.map(b=>{const rs=series[b.id].slice(start,end),valid=rs.filter(r=>r.p!==null),avg=valid.reduce((s,r)=>s+r.p,0)/Math.max(valid.length,1),count=D.alerts.filter(a=>a.building===b.id&&a.start<end&&a.end>start).length;return `<button class="building-card" data-building="${b.id}"><div class="building-top"><div class="building-icon">▥</div><div><strong>${esc(b.name)}</strong><small>${b.kind}</small></div><i class="signal-dot ${count?'warn':''}"></i></div><div class="building-bottom"><div><b>${fmt(avg)} <small>kW</small></b><br><span>mean net demand · ${count} ${count===1?'alert':'alerts'}</span></div>${spark(rs)}</div></button>`}).join('');
 $('#overview-alerts').innerHTML=alertTable(va.slice(0,5));bindDynamic();}
function spark(rs){const vals=rs.filter(r=>r.p!==null).filter((_,i)=>i%Math.max(1,Math.floor(rs.length/48))===0).map(r=>r.p);const min=Math.min(...vals),max=Math.max(...vals);return `<svg class="spark" viewBox="0 0 105 30" aria-hidden="true"><polyline points="${vals.map((v,j)=>`${j/Math.max(1,vals.length-1)*105},${27-(v-min)/(max-min||1)*24}`).join(' ')}" fill="none" stroke="#88a479" stroke-width="1.3"/></svg>`}
function bindDynamic(){$$('[data-alert]').forEach(el=>{el.onclick=()=>openAlert(el.dataset.alert);el.onkeydown=e=>{if(e.key==='Enter'||e.key===' '){e.preventDefault();el.click()}}});$$('[data-building]').forEach(el=>el.onclick=()=>{$('#building').value=el.dataset.building;render()});$$('[data-page]').forEach(el=>el.onclick=()=>navigate(el.dataset.page))}
function renderInboxBase(){const va=visibleAlerts().filter(a=>matchesAlertFilters(a)).filter(a=>$('#status-filter').value==='all'||state(a)===$('#status-filter').value);if(!InsightUI.drilldownAlert()&&!va.some(a=>a.id===selected))selected=va[0]?.id;$('#alert-total').textContent=va.length;$('#inbox').innerHTML=va.length?va.map(a=>`<button class="alert-row ${a.id===selected?'selected':''}" data-select="${a.id}"><div class="row-meta"><span>${building(a.building).name}</span><span class="badge ${severityClass(a)}">${a.priority}</span></div><strong>${esc(guessTitle(a))}</strong><small>${stamp(a.start)} PDT · ${fmt((a.end-a.start)*.25,2)} h flagged</small><div class="row-meta" style="margin-top:12px"><span>${a.id} · ${state(a)}</span><span>Review →</span></div></button>`).join(''):'<div class="empty">No alerts match the current filters.</div>';$$('[data-select]').forEach(el=>el.onclick=()=>{InsightUI.clearDrilldown();selected=el.dataset.select;renderInbox();WorkspaceUI.focusInvestigation()});const a=InsightUI.drilldownAlert()||va.find(a=>a.id===selected),panel=$('#investigation');if(!a){panel.innerHTML='<div class="empty">Select a different window or status to investigate an alert.</div>';return}
 const rs=series[a.building],segment=rs.slice(a.start,a.end),first=segment[0],mx=Math.max(...segment.filter(r=>r.p!==null).map(r=>r.p)),view=WorkspaceUI.boundsFor(a,D.days*96),display=rs.slice(view.start,view.end);
 panel.innerHTML=`<div class="overline">${a.id} · ${state(a).toUpperCase()} · ${role==='manager'?'FACILITY REVIEW':'ENGINEERING INVESTIGATION'}</div><div class="investigation-severity ${severityClass(a)}">${severityBadge(a)} <span>${esc(a.detection_layer||'Interval rule')}</span></div><h2>${esc(guessTitle(a))}</h2><p>${building(a.building).name} · ${stamp(a.start)} – ${stamp(a.end)} PDT (end exclusive)</p><div class="evidence-grid"><div><small>Flagged duration</small><b>${fmt((a.end-a.start)*.25,2)} h</b></div><div><small>${a.kind==='demand'?'Excess residual':'Peak observed'}</small><b>${a.kind==='demand'?fmt(a.excess_kwh)+' kWh':Number.isFinite(mx)?fmt(mx)+' kW':'Missing'}</b></div><div><small>Peak residual score</small><b>${fmt(a.peak_score,1)}</b></div></div><div id="detail-chart" class="chart"></div><div class="legend" style="padding:0 0 20px"><span><i class="line-swatch"></i>Observed</span><span><i class="line-swatch dashed"></i>Expected</span><span>Red = high · Yellow = medium</span></div><div class="callout"><strong>Suggested next step</strong><br>${esc(a.next_step||advice[a.kind]||'Review the pattern and its operating context.')}</div>${role==='engineer'?`<div class="technical"><h3>At the first flagged interval</h3><table><tr><td>Active power / expected</td><td>${first.p===null?'Missing':fmt(first.p,1)+' kW'} / ${fmt(first.expected,1)} kW</td></tr><tr><td>Reactive power / expected</td><td>${first.q===null?'Missing':fmt(first.q,1)} / ${fmt(first.expected_q,1)} kvar</td></tr><tr><td>Power factor magnitude</td><td>${first.pf===null?'Missing':fmt(first.pf,3)}</td></tr><tr><td>Line-to-line voltage</td><td>${first.v===null?'Missing':fmt(first.v,1)+' V'}</td></tr><tr><td>Balanced equivalent current</td><td>${first.amps===null?'Missing':fmt(first.amps,1)+' A'}</td></tr><tr><td>Robust demand score threshold</td><td>${building(a.building).threshold}</td></tr><tr><td>Outdoor temperature</td><td>${fmt(first.temp,1)} °C</td></tr></table><p class="small">Rule: ${a.kind==='context'?'History-based rule; see the sequence evidence and threshold below':a.kind==='demand'?'|P − expected| / robust scale ≥ frozen per-meter threshold':a.kind==='missing'?'P is missing; no zero fill':a.kind==='stale'?'At least 8 consecutive identical active-power readings':'PF < 0.75 and Q > 1.6 × training slot median'}. Residual scores are not probabilities. These are synthetic electrical values.</p></div>`:''}<div class="actions"><button class="button dark" id="review">✓ Mark reviewed</button><button class="button light" id="dismiss">Dismiss</button>${state(a)!=='new'?'<button class="text-button" id="reopen">Reopen</button>':''}</div><p class="small" style="margin-top:13px">Review status is stored in this browser only.</p>`;
 drawChart('#detail-chart',display,{alerts:[a],height:225,threshold:building(a.building).threshold,title:labels[a.kind],supportWindows:WorkspaceUI.supportingWindows(a)});
 for(const [id,value] of [['review','reviewed'],['dismiss','dismissed'],['reopen','new']])if($('#'+id))$('#'+id).onclick=()=>{states[a.id]=value;try{localStorage.setItem('meterwise-review-v2',JSON.stringify(states))}catch(e){}render();notify('Alert '+value)};
}
function runScenario(){const bid=$('#lab-building').value||'ADM',b=building(bid),type=$('#lab-type').value,mag=Number($('#magnitude').value),dur=Number($('#duration').value),hour=Number($('#lab-hour').value),begin=hour*4,end=Math.min(96,begin+(type==='spike'?1:dur*4));$('#magnitude-label').textContent=mag+' kW';$('#duration-label').textContent=(type==='spike'?'0.25':dur)+' hours';$('#magnitude').disabled=['dropout','flatline'].includes(type);$('#duration').disabled=type==='spike';let repeated=0;
 scenarioRows=series[bid].slice(14*96,15*96).map((r,j)=>{let p=r.clean,truth=j>=begin&&j<end;if(truth){if(type==='dropout')p=null;else if(type==='flatline')p=series[bid][14*96+Math.max(0,begin-1)].clean;else p+=type==='drift'?mag*(j-begin+1)/(end-begin):mag}return {...r,p,truth,flag:'',scenario_type:type}});
 repeated=1;scenarioRows.forEach((r,j)=>{repeated=j&&r.p!==null&&r.p===scenarioRows[j-1].p?repeated+1:1;r.score=r.p===null?0:Math.abs(r.p-r.expected)/r.scale;r.flag=r.p===null?'missing':repeated>=8?'stale':r.score>=b.threshold?'demand':''});
 const hits=scenarioRows.filter(r=>r.truth&&r.flag),extra=scenarioRows.filter(r=>!r.truth&&r.flag).length,delay=hits.length?(hits[0].i-(14*96+begin))*15:null;
 drawChart('#lab-chart',scenarioRows,{threshold:b.threshold,height:330,alerts:scenarioRows.filter(r=>r.flag).map(r=>({start:r.i,end:r.i+1,priority:r.flag==='missing'||r.score>=8?'High':'Medium',likely_type:labels[r.flag]||'Demand deviation'})),title:'Scenario demand'});
 $('#scenario-result').innerHTML=`<strong>${hits.length?'The detector flags this scenario.':'No detection within the injected window.'}</strong><br>${hits.length?'First alert '+delay+' minutes after injection.':'Try a stronger or longer deviation.'} ${hits.length} of ${end-begin} injected intervals flagged. ${extra} additional flagged intervals outside the injection.<br><span class="small">${building(bid).name} · Sep 7, 2026 PDT · ${type==='spike'?'single 15-minute interval':dur+' hours requested'} · threshold ${b.threshold}. The plot shows net kW; missing values remain gaps.</span>`;
}
function renderBenchmarkBase(){const events=D.events.filter(e=>e.split==='test'),alerts=D.alerts.filter(a=>a.split==='test'),matches=events.map(e=>({e,hit:alerts.filter(a=>overlaps(a,e))})),detected=matches.filter(m=>m.hit.length),correct=alerts.filter(a=>events.some(e=>overlaps(a,e))),falseAlerts=alerts.length-correct.length,delays=detected.map(m=>(Math.max(m.e.start,Math.min(...m.hit.map(a=>a.start)))-m.e.start)*15).sort((a,b)=>a-b),median=delays.length%2?delays[Math.floor(delays.length/2)]:(delays[delays.length/2-1]+delays[delays.length/2])/2;
 $('#benchmark').innerHTML=kpi('Event recall',fmt(detected.length/events.length*100),'%',`${detected.length} / ${events.length} injected test events`)+kpi('Grouped alert precision',fmt(correct.length/Math.max(1,alerts.length)*100),'%',`${correct.length} / ${alerts.length} episodes overlap truth`)+kpi('False alerts / meter-day',fmt(falseAlerts/(6*14),2),'',`${falseAlerts} unmatched episodes / 84 meter-days`)+kpi('Median detection delay',delays.length?fmt(median):'—','min',`${events.length-detected.length} missed events · excluded from median`);
 $('#event-results').innerHTML=`<table class="alert-table"><thead><tr><th>Injected event</th><th>Building</th><th>Detection delay</th><th>Type</th><th>Result</th></tr></thead><tbody>${matches.map(({e,hit})=>`<tr><td class="title">${e.title}<small>${stamp(e.start)} PDT</small></td><td>${building(e.building).name}</td><td>${hit.length?fmt((Math.max(e.start,Math.min(...hit.map(a=>a.start)))-e.start)*15)+' min':'—'}</td><td>${e.type}</td><td><span class="badge ${hit.length?'status':''}">${hit.length?'Detected':'Missed'}</span></td></tr>`).join('')}</tbody></table>`;
}
function csvDownload(name,rows){if(!rows.length){notify('No rows to export');return}const fields=Object.keys(rows[0]),quote=v=>'"'+String(v??'').replaceAll('"','""')+'"',text=[fields.map(quote).join(','),...rows.map(r=>fields.map(k=>quote(r[k])).join(','))].join('\r\n'),url=URL.createObjectURL(new Blob([text],{type:'text/csv;charset=utf-8'}));const a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);notify('CSV export ready')}
async function init(){try{const response=await fetch('data/simulation.json');if(!response.ok)throw new Error('Dataset could not be loaded');const rawData=await response.text();D=JSON.parse(rawData);await WorkspaceUI.init(D,rawData);series=Object.fromEntries(Object.entries(D.series).map(([k,rows])=>[k,rows.map(values=>Object.fromEntries(D.fields.map((key,i)=>[key,values[i]])))]));InsightUI.init(D,series);for(const b of D.buildings){$('#building').add(new Option(b.name,b.id));$('#lab-building').add(new Option(b.name,b.id))}
 $('#manager').onclick=()=>setRole('manager');$('#engineer').onclick=()=>setRole('engineer');for(const id of ['building','window','date'])$('#'+id).onchange=()=>{if(id==='date'){let val=$('#date').value;$('#date').value=val<'2026-10-05'?'2026-10-05':val>'2026-10-18'?'2026-10-18':val||'2026-10-16'}render()};$('#status-filter').onchange=renderInbox;$('#severity-filter').onchange=renderInbox;$('#signal-filter').onchange=renderInbox;
 $('#export').onclick=()=>{const {start,end}=bounds();csvDownload('meterwise-filtered-readings.csv',ids().flatMap(id=>series[id].slice(start,end)))};$('#scenario-export').onclick=()=>csvDownload('meterwise-scenario.csv',scenarioRows.map(({i,t,building,temp,p,expected,scale,score,flag,truth,scenario_type})=>({i,t,building,temp,p,expected,scale,score,flag,truth,scenario_type})));$('#help').onclick=()=>navigate('data');for(const id of ['lab-building','lab-type','magnitude','duration','lab-hour'])$('#'+id).oninput=runScenario;$('#run-scenario').onclick=()=>{runScenario();notify('Scenario recalculated with the frozen detector')};bindDynamic();navigate(['overview','alerts','lab','data'].includes(location.hash.slice(1))?location.hash.slice(1):'overview');window.addEventListener('hashchange',()=>{let next=location.hash.slice(1);if(next!==page&&['overview','alerts','lab','data'].includes(next))navigate(next)});
 }catch(e){$('main').innerHTML='<div class="error"><h2>The dataset could not be loaded.</h2><p>Open this prototype through a local HTTP server or its hosted Site URL. '+esc(e.message)+'</p></div>';console.error(e)}}
function setRole(value){role=value;$('#manager').classList.toggle('active',role==='manager');$('#engineer').classList.toggle('active',role==='engineer');render();notify(role==='engineer'?'Engineering details enabled in alert investigations':'Manager review view enabled')}

function severityClass(a){return a.priority==='High'?'high':'medium'}
function severityBadge(a){return `<span class="badge severity ${severityClass(a)}">${a.priority==='High'?'▲ High':'◆ Medium'}</span>`}
function guessTitle(a){return a.likely_type||labels[a.kind]||'Unusual meter pattern'}
function matchesAlertFilters(a,includeFeedback=true){const priority=$('#severity-filter').value,layer=$('#signal-filter').value;const contextual=a.kind==='context'||a.related_ids?.length;return (priority==='all'||a.priority===priority)&&(layer==='all'||(layer==='context'?contextual:!contextual))&&(!includeFeedback||WorkspaceUI.matchesFeedback(a))}
function openAlert(id){InsightUI.clearDrilldown();WorkspaceUI.alertSelected(id);const a=D.alerts.find(a=>a.id===id);if(!a)return;selected=id;const {start,end}=bounds();if(!ids().includes(a.building))$('#building').value='ALL';if(a.start>=end||a.end<=start){$('#date').value=rowOf(a.building,a.start).t.slice(0,10);$('#window').value='14'}$('#severity-filter').value='all';$('#signal-filter').value='all';$('#status-filter').value='all';navigate('alerts');WorkspaceUI.focusInvestigation()}
function showPriority(priority){$('#severity-filter').value=priority;$('#signal-filter').value='all';$('#status-filter').value='all';navigate('alerts')}
function showContext(){const {start,end}=bounds();if(!D.alerts.some(a=>a.kind==='context'&&ids().includes(a.building)&&a.start<end&&a.end>start)){$('#date').value='2026-10-18';$('#window').value='14';$('#building').value='ALL'}$('#signal-filter').value='context';$('#severity-filter').value='all';$('#status-filter').value='all';navigate('alerts')}
function contextTimeline(a){const events=a.evidence_events||[];const notes=a.context_notes||[];const related=(a.related_ids||[]).map(id=>D.alerts.find(x=>x.id===id)).filter(Boolean);if(!events.length&&!notes.length&&!related.length)return `<div class="context-evidence"><h3>What additional context would help?</h3><p>Compare equipment/BMS logs and neighboring meters at this time. The current explanation is based on the observed interval pattern; no equipment cause has been confirmed.</p></div>`;
 return `<section class="context-evidence"><div class="overline">WHY CONTEXT MATTERS</div><h3>${a.kind==='context'?'The sequence is the signal':'Related events change the interpretation'}</h3>${notes.map(n=>`<p>${esc(n)}</p>`).join('')}${events.length?`<div class="context-timing">Evidence begins ${stamp(Math.min(a.evidence_start,...events.map(e=>e.start)))} PDT<br><strong>Alert first raised ${stamp(a.detected_at)} PDT</strong><br>Earlier readings provide context; detections are not backdated.</div><ol class="evidence-timeline">${events.map((e,i)=>`<li><div class="timeline-marker">${i+1}</div><div><strong>${esc(e.label)}</strong><time>${stamp(e.start)} – ${stamp(e.end)} PDT</time><p>Observed mean <b>${fmt(e.mean_kw,1)} kW</b> · expected ${fmt(e.expected_kw,1)} kW<br>Mean signed score ${fmt(e.mean_score,2)} · point limit ${fmt(e.point_threshold,2)}<br>${e.point_flags} point-rule flags in this evidence window</p></div></li>`).join('')}</ol>`:''}${related.length?`<div class="related-events"><h4>Linked detections</h4>${related.map(r=>`<button class="related-alert ${severityClass(r)}" data-related="${r.id}">${severityBadge(r)}<span>${esc(building(r.building).name)} · ${esc(guessTitle(r))}<small>${stamp(r.start)} PDT</small></span><b>↗</b></button>`).join('')}</div>`:''}</section>`;
}
function renderContextSummary(va){const history=va.filter(a=>a.kind==='context').sort((a,b)=>(a.priority==='High'?0:1)-(b.priority==='High'?0:1)||b.start-a.start),linked=va.filter(a=>a.kind==='missing'&&a.related_ids?.length),unique=new Map();for(const a of history){if(!unique.has(a.context_type))unique.set(a.context_type,a)}if(linked.length)unique.set('shared_missing',linked[0]);let examples=[...unique.values()].slice(0,3);$('#context-summary').innerHTML=`<div class="section-heading"><div><h2>When one reading isn’t enough</h2><p>Repeated events, sustained sequences, and coincident meter behavior.</p></div><button class="text-button" id="context-filter-button">Explore context alerts →</button></div><div class="context-cards">${examples.length?examples.map(a=>`<article class="context-card ${severityClass(a)}"><div class="context-card-top">${severityBadge(a)}<span class="context-label">${a.kind==='context'?'HISTORY REQUIRED':'MULTIPLE METERS'}</span></div><h3>${esc(a.kind==='missing'?'Coincident telemetry gaps':guessTitle(a))}</h3><p>${esc(a.kind==='missing'?'Several meters stop reporting in the same interval. A shared collection issue is possible.':a.hypothesis)}</p><div class="context-card-foot"><span>${esc(building(a.building).name)} · ${stamp(a.start)}</span><button class="text-button" data-alert="${a.id}">See the evidence ↗</button></div></article>`).join(''):'<div class="card empty">No history-based detections match this selection. Explore the complete test period to inspect the contextual examples.</div>'}</div>`;$('#context-filter-button').onclick=showContext;}
function renderOverview(){renderOverviewBase();const va=visibleAlerts(),high=va.filter(a=>a.priority==='High'),medium=va.filter(a=>a.priority==='Medium'),context=va.filter(a=>a.kind==='context');$('#anomaly-summary').innerHTML=va.length?`<div class="summary-message"><span class="summary-symbol">${high.length?'▲':'◆'}</span><div><strong>Anomalies detected in the selected window</strong><p>${va.length} alert episodes · ${context.length} require history or a sequence. Investigate the evidence before assigning a cause.</p></div></div><div class="severity-buttons"><button class="severity-button high" id="show-high"><b>${high.length}</b> High priority</button><button class="severity-button medium" id="show-medium"><b>${medium.length}</b> Medium priority</button></div>`:'<div class="summary-message"><strong>No anomalies detected in this window</strong></div>';$('#anomaly-summary').className='anomaly-summary '+(high.length?'high':va.length?'medium':'clear');if($('#show-high'))$('#show-high').onclick=()=>showPriority('High');if($('#show-medium'))$('#show-medium').onclick=()=>showPriority('Medium');
 const focus=va.find(a=>state(a)==='new')||va[0],attention=$('.attention');attention.dataset.priority=focus?.priority||'';attention.querySelector('h2').innerHTML=focus?'Anomaly detected.<br>Start with the evidence.':'No alerts in this window.';if(focus)$('#spotlight').innerHTML=`${severityBadge(focus)}<div class="context-label">${esc(focus.detection_layer)}</div><h3>${esc(guessTitle(focus))}</h3><p>${esc(focus.hypothesis)}</p><div class="spotlight-meter">${esc(building(focus.building).name)} · ${stamp(focus.start)} PDT</div><button class="button" data-alert="${focus.id}">Understand this anomaly ↗</button><div class="tiny">Working hypothesis · requires confirmation</div>`;
 if(role==='manager'&&high.length)$('#kpis').children[1]?.classList.add('alarming');const {start,end}=bounds();$$('.building-card').forEach(el=>{const found=D.alerts.filter(a=>a.building===el.dataset.building&&a.start<end&&a.end>start);if(!found.length)return;const high=found.some(a=>a.priority==='High');el.classList.add('severity-'+(high?'high':'medium'));el.querySelector('.signal-dot').className='signal-dot '+(high?'high':'medium');el.querySelector('.building-top').insertAdjacentHTML('afterend',`<div class="building-priority ${high?'high':'medium'}">${high?'▲ High':'◆ Medium'} priority signal</div>`)});renderContextSummary(va);InsightUI.renderGroups('#linked-overview',va);bindDynamic();}
function renderInbox(){InsightUI.renderGroups('#linked-inbox',visibleAlerts().filter(a=>matchesAlertFilters(a)).filter(a=>$('#status-filter').value==='all'||state(a)===$('#status-filter').value));renderInboxBase();WorkspaceUI.inboxSummary();const a=D.alerts.find(a=>a.id===selected);$$('.alert-row').forEach(el=>{const item=D.alerts.find(x=>x.id===el.dataset.select);el.classList.add('severity-'+severityClass(item));el.querySelector('strong').insertAdjacentHTML('afterend',`<span class="alert-guess">${esc(item.hypothesis||'Review the measured deviation.')}</span>${item.kind==='context'?'<span class="context-label">REQUIRES HISTORY / MULTIPLE OBSERVATIONS</span>':''}`)});if(!a||!$('#investigation h2'))return;const panel=$('#investigation');panel.dataset.priority=a.priority;panel.querySelector('.evidence-grid').insertAdjacentHTML('beforebegin',`<section class="pattern-explainer"><div class="overline">WORKING HYPOTHESIS · UNCONFIRMED</div><h3>${esc(a.hypothesis)}</h3><p><strong>What was observed:</strong> ${esc(a.explanation)}</p><details><summary>Other plausible explanations</summary><p>${esc(a.alternatives)}</p></details></section>`);panel.querySelector('.callout').insertAdjacentHTML('beforebegin',contextTimeline(a));panel.querySelector('.actions').insertAdjacentHTML('beforebegin',`<p class="severity-explanation">${esc(a.severity_reason)}</p>`);panel.querySelectorAll('[data-related]').forEach(el=>el.onclick=()=>openAlert(el.dataset.related));WorkspaceUI.investigation(a);InsightUI.investigation(a);}
function alertTable(alerts){return !alerts.length?'<div class="card empty">No detected alerts match this view.</div>':`<table class="alert-table"><thead><tr><th>Likely anomaly / building</th><th>First detected · PDT</th><th>Priority</th><th>Evidence</th><th>Status</th></tr></thead><tbody>${alerts.map(a=>`<tr class="severity-${severityClass(a)}" data-alert="${a.id}" tabindex="0" role="button" aria-label="Investigate ${esc(guessTitle(a))} at ${esc(building(a.building).name)}"><td class="title">${esc(guessTitle(a))}<small>${esc(building(a.building).name)} · ${esc(a.detection_layer)}</small><small class="table-hypothesis">${esc(a.hypothesis)}</small></td><td>${stamp(a.start)}</td><td>${severityBadge(a)}</td><td>${a.kind==='demand'||a.kind==='context'?fmt(a.excess_kwh)+' kWh residual':fmt((a.end-a.start)*.25,2)+' hours flagged'}</td><td><span class="badge status">${state(a)}</span></td></tr>`).join('')}</tbody></table>`}

function renderBenchmark(){renderBenchmarkBase();const events=D.events.filter(e=>e.split==='test'),all=D.alerts.filter(a=>a.split==='test'),point=all.filter(a=>a.kind!=='context'),contexts=all.filter(a=>a.kind==='context'),count=as=>events.filter(e=>as.some(a=>overlaps(a,e))).length,pointCount=count(point),allCount=count(all),unmatched=as=>as.filter(a=>!events.some(e=>overlaps(a,e))).length;let panel=$('#layer-comparison');if(!panel){$('#benchmark').insertAdjacentHTML('afterend','<section id="layer-comparison" class="layer-comparison"></section>');panel=$('#layer-comparison')}panel.innerHTML=`<h3>What extra context adds</h3><div class="layer-stats"><div><strong>${pointCount} / ${events.length}</strong><span>events detected by interval rules</span><small>${unmatched(point)} unmatched alert episodes</small></div><div><strong>${allCount} / ${events.length}</strong><span>events detected with history rules added</span><small>${unmatched(all)} unmatched episodes across both layers</small></div></div><p><b>${allCount-pointCount} injected event(s) are detected only after accumulating context.</b> The history layer adds ${contexts.length} test-period episodes, including ${unmatched(contexts)} unmatched episodes. Extra context can improve detection and also create more false alerts.</p><p class="small">Known injection labels are used only here for evaluation. Hypotheses in the alert inbox use observed measurements and prior events.</p>`;}
init();
